return items.map((item) => {
  const b = item.json.body || item.json;
  let payload = b.payload || {};
  if ((!payload || typeof payload !== 'object' || Array.isArray(payload)) && typeof b.payload_json === 'string' && b.payload_json.trim()) {
    try {
      payload = JSON.parse(b.payload_json);
    } catch {
      payload = {};
    }
  }
  return {
    json: {
      id_candidato: String(b.id_candidato || '').trim(),
      lider_id: String(b.lider_id || '').trim(),
      recurso: String(b.recurso || '').trim(),
      acao: String(b.acao || 'upsert').trim(),
      referencia_id: String(b.referencia_id || '').trim(),
      payload,
      observacao: String(b.observacao || '').trim()
    }
  };
});

const perm = Array.isArray($json) ? $json[0] : $json;
const src = $item(0).$node['Normalizar Solicitação'].json;
const p = src.payload || {};
function esc(v){ return String(v ?? '').replace(/'/g, "''"); }
let selectBefore = '';
let upsertSql = '';
if (src.recurso === 'agenda') {
  selectBefore = `select row_to_json(t) as before_json from (select * from agendas_campanha where id = '${esc(src.referencia_id)}'::uuid) t;`;
  upsertSql = `insert into agendas_campanha (id, id_candidato, titulo, descricao, data_inicio, data_fim, local_nome, endereco, cidade, uf, canal_confirmacao, status, origem_dados, criado_por_lider_id, atualizado_por_lider_id, metadata) values (coalesce(nullif('${esc(src.referencia_id)}','')::uuid, gen_random_uuid()), '${esc(src.id_candidato)}', '${esc(p.titulo)}', '${esc(p.descricao)}', '${esc(p.data_inicio)}'::timestamptz, nullif('${esc(p.data_fim)}','')::timestamptz, '${esc(p.local_nome)}', '${esc(p.endereco)}', '${esc(p.cidade)}', '${esc(p.uf)}', '${esc(p.canal_confirmacao)}', '${esc(p.status || 'planejado')}', 'lider_campanha', '${esc(src.lider_id)}'::uuid, '${esc(src.lider_id)}'::uuid, '${esc(JSON.stringify(p.metadata || {}))}'::jsonb) on conflict (id) do update set titulo = excluded.titulo, descricao = excluded.descricao, data_inicio = excluded.data_inicio, data_fim = excluded.data_fim, local_nome = excluded.local_nome, endereco = excluded.endereco, cidade = excluded.cidade, uf = excluded.uf, canal_confirmacao = excluded.canal_confirmacao, status = excluded.status, atualizado_por_lider_id = excluded.atualizado_por_lider_id, metadata = excluded.metadata, atualizado_em = now() returning id;`;
} else if (src.recurso === 'evento') {
  selectBefore = `select row_to_json(t) as before_json from (select * from eventos_campanha where id = '${esc(src.referencia_id)}'::uuid) t;`;
  upsertSql = `insert into eventos_campanha (id, agenda_id, id_candidato, nome_evento, tipo_evento, descricao, data_evento, local_nome, endereco, cidade, uf, capacidade_estimada, link_confirmacao, status, origem_dados, criado_por_lider_id, atualizado_por_lider_id, metadata) values (coalesce(nullif('${esc(src.referencia_id)}','')::uuid, gen_random_uuid()), nullif('${esc(p.agenda_id)}','')::uuid, '${esc(src.id_candidato)}', '${esc(p.nome_evento)}', '${esc(p.tipo_evento)}', '${esc(p.descricao)}', '${esc(p.data_evento)}'::timestamptz, '${esc(p.local_nome)}', '${esc(p.endereco)}', '${esc(p.cidade)}', '${esc(p.uf)}', ${Number(p.capacidade_estimada || 0)}, '${esc(p.link_confirmacao)}', '${esc(p.status || 'ativo')}', 'lider_campanha', '${esc(src.lider_id)}'::uuid, '${esc(src.lider_id)}'::uuid, '${esc(JSON.stringify(p.metadata || {}))}'::jsonb) on conflict (id) do update set agenda_id = excluded.agenda_id, nome_evento = excluded.nome_evento, tipo_evento = excluded.tipo_evento, descricao = excluded.descricao, data_evento = excluded.data_evento, local_nome = excluded.local_nome, endereco = excluded.endereco, cidade = excluded.cidade, uf = excluded.uf, capacidade_estimada = excluded.capacidade_estimada, link_confirmacao = excluded.link_confirmacao, status = excluded.status, atualizado_por_lider_id = excluded.atualizado_por_lider_id, metadata = excluded.metadata, atualizado_em = now() returning id;`;
} else {
  selectBefore = `select row_to_json(t) as before_json from (select * from canais_integracao where id = '${esc(src.referencia_id)}'::uuid) t;`;
  upsertSql = `insert into canais_integracao (id, id_candidato, nome_canal, tipo_canal, identificador_externo, url_canal, status, origem_dados, criado_por_lider_id, atualizado_por_lider_id, metadata) values (coalesce(nullif('${esc(src.referencia_id)}','')::uuid, gen_random_uuid()), '${esc(src.id_candidato)}', '${esc(p.nome_canal)}', '${esc(p.tipo_canal)}', '${esc(p.identificador_externo)}', '${esc(p.url_canal)}', '${esc(p.status || 'ativo')}', 'lider_campanha', '${esc(src.lider_id)}'::uuid, '${esc(src.lider_id)}'::uuid, '${esc(JSON.stringify(p.metadata || {}))}'::jsonb) on conflict (id) do update set nome_canal = excluded.nome_canal, tipo_canal = excluded.tipo_canal, identificador_externo = excluded.identificador_externo, url_canal = excluded.url_canal, status = excluded.status, atualizado_por_lider_id = excluded.atualizado_por_lider_id, metadata = excluded.metadata, atualizado_em = now() returning id;`;
}
return [{ json: { ...src, permissao: perm, select_before: selectBefore, upsert_sql: upsertSql } }];

const beforeRow = Array.isArray($item(0).$node['Ler Estado Anterior'].json) ? $item(0).$node['Ler Estado Anterior'].json[0] : $item(0).$node['Ler Estado Anterior'].json;
const afterRow = Array.isArray($json) ? $json[0] : $json;
const src = $item(0).$node['Montar SQL Governança'].json;
return [{ json: { ...src, before_json: beforeRow?.before_json || null, after_id: afterRow?.id || src.referencia_id, after_json: src.payload || {} } }];
